<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,reactive,watch} from 'vue';
import {request} from '../api';
import type {AnalyticsDrillFilters} from '../../../../packages/contracts/src/analytics';
import {AnalyticsController,createAnalyticsState,analyticsBusy,quantityLabel,coverageLabel,beijingTime,barWidth,periodRangeLabel,drillPeriodLabel,periodOrderNotice} from '../../../../packages/analytics-client/src';
const props=defineProps<{locked?:boolean}>();
const emit=defineEmits<{(e:'busy-changed',busy:boolean):void;(e:'failure',error:unknown):void;(e:'openOrder',orderId:string):void}>();
const state=reactive(createAnalyticsState()),controller=new AnalyticsController(path=>request(path),(path,body)=>request(path,'POST',body as Record<string,unknown>),state,e=>emit('failure',e));
const busy=computed(()=>analyticsBusy(state)),locked=computed(()=>busy.value||!!props.locked),snapshot=computed(()=>state.snapshot),hospitalLabels=computed(()=>['权限内全部医院',...state.hospitals.map(h=>h.name)]),hospitalIndex=computed(()=>state.hospitals.findIndex(h=>h.id===state.form.hospitalId)+1),trend=computed(()=>state.trend==='confirmation'?snapshot.value?.charts.confirmationTrend||[]:snapshot.value?.charts.demandTrend||[]);
const maxOrders=computed(()=>Math.max(1,...(snapshot.value?.charts.frequency||[]).map(r=>r.orders))),maxQuantity=computed(()=>Math.max(1,...(snapshot.value?.charts.quantity||[]).flatMap(r=>[Number(r.demandQuantity),Number(r.confirmedQuantity)||0]))),maxRanking=computed(()=>Math.max(1,...(snapshot.value?.charts.ranking||[]).map(r=>Number(r.demandQuantity)))),maxShortage=computed(()=>Math.max(1,...(snapshot.value?.charts.shortage||[]).map(r=>(Number(r.confirmedQuantity)||0)+(Number(r.missingQuantity)||0))));
const plotWidth=computed(()=>Math.max(620,trend.value.length*260+30)),plotPoints=computed(()=>{const values=trend.value.map(r=>state.trend==='confirmation'?r.confirmedQuantity:r.demandQuantity),max=Math.max(1,...values.map(v=>Number(v)||0));return trend.value.map((r,i)=>({period:r.period,label:periodRangeLabel(r),notice:periodOrderNotice(r),value:values[i],x:130+i*260,y:200-(Number(values[i])||0)/max*135}));}),plotLines=computed(()=>plotPoints.value.slice(1).flatMap((p,i)=>{const prev=plotPoints.value[i];if(p.value===null||prev.value===null)return [];const dx=p.x-prev.x,dy=p.y-prev.y;return [{left:prev.x,top:prev.y,width:Math.sqrt(dx*dx+dy*dy),angle:Math.atan2(dy,dx)*180/Math.PI}];}));
const selectedPeriod=computed(()=>drillPeriodLabel(snapshot.value,state.selection));
const pages=computed(()=>state.drill?Math.max(1,Math.ceil(state.drill.total/state.drill.pageSize)):1),changed=computed(()=>{const f=snapshot.value?.filters;return !!f&&['receivedFrom','receivedTo','hospitalId','name','spec','groupBy'].some(k=>(state.form[k as keyof typeof state.form]||'')!==(f[k as keyof typeof f]||''));});
const picked=(e:unknown)=>(e as {detail:{value:string}}).detail.value;
function hospitalChanged(e:unknown){state.form.hospitalId=state.hospitals[Number(picked(e))-1]?.id;}
function drill(filter:AnalyticsDrillFilters){if(!locked.value)void controller.drill(filter);}
function openOrder(id:string){if(!locked.value&&!controller.expire())emit('openOrder',id);}
async function refresh(){if(!locked.value)await controller.query();}
watch(busy,value=>emit('busy-changed',value),{immediate:true,flush:'sync'});
let expiryTimer:ReturnType<typeof setInterval>|undefined;
onMounted(()=>{void controller.bootstrap();expiryTimer=setInterval(()=>controller.expire(),1000);});onBeforeUnmount(()=>{clearInterval(expiryTimer);controller.dispose();emit('busy-changed',false);});defineExpose({refresh,canLeave:()=>!busy.value});
</script>
<template>
 <view class="hospital-analytics">
  <text class="eyebrow">需求与最终确认结果</text><text class="title">医院数据分析</text><text class="muted">本人订单及当前负责医院的历史。确认量不代表实际发货，数量单位 kg。</text>
  <view class="filters"><view class="date-row"><view class="field"><text>接收日期自</text><picker mode="date" :value="state.form.receivedFrom" :disabled="locked" @change="state.form.receivedFrom=picked($event)"><view class="select">{{state.form.receivedFrom}} ⌄</view></picker></view><view class="field"><text>至（含当天）</text><picker mode="date" :value="state.form.receivedTo" :disabled="locked" @change="state.form.receivedTo=picked($event)"><view class="select">{{state.form.receivedTo}} ⌄</view></picker></view></view><view class="field"><text>医院</text><picker :range="hospitalLabels" :value="hospitalIndex" :disabled="locked" @change="hospitalChanged"><view class="select">{{hospitalLabels[hospitalIndex]}} ⌄</view></picker></view><view class="date-row"><label class="field"><text>药品</text><input v-model="state.form.name" placeholder="药品名称" maxlength="100" :disabled="locked" /></label><label class="field"><text>规格</text><input v-model="state.form.spec" placeholder="规格" maxlength="200" :disabled="locked" /></label></view><view class="field"><text>趋势分组</text><picker :range="['自然月','自然周 · 周一开始']" :value="state.form.groupBy==='week'?1:0" :disabled="locked" @change="state.form.groupBy=picked($event)==='1'?'week':'month'"><view class="select">{{state.form.groupBy==='week'?'自然周 · 周一开始':'自然月'}} ⌄</view></picker></view><button class="primary" :disabled="locked" @click="refresh">查询 / 整组刷新</button></view>
  <view v-if="state.hospitalError" class="error"><text>医院选项读取失败：{{state.hospitalError}}</text><button :disabled="locked" @click="controller.hospitals()">重新读取</button></view><view v-if="changed" class="notice">筛选已修改，请查询后更新；下方仍是上次查询结果。</view><view v-if="state.error" class="error"><text>{{state.error}}</text><button :disabled="locked" @click="refresh">重新查询</button></view><text v-if="state.loading" class="empty">正在生成分析快照…</text>
  <template v-if="snapshot"><view class="meta"><text>{{snapshot.filters.receivedFrom}} — {{snapshot.filters.receivedTo}}</text><text>数据截至 {{beijingTime(snapshot.asOf)}}</text><text>{{beijingTime(snapshot.expiresAt)}} 到期</text><text class="tiny">查询 {{snapshot.snapshotId}}</text></view><view class="summary"><view><text class="tiny">要货次数</text><text class="stat">{{snapshot.summary.orders}} 单</text></view><view><text class="tiny">采购需求（含缺货）</text><text class="stat">{{snapshot.summary.demandQuantity}} kg</text></view></view><text class="confirmation-stat">确认可供货 {{quantityLabel(snapshot.summary.confirmedQuantity,snapshot.summary.coverage,'confirmed')}}</text><text class="coverage">{{coverageLabel(snapshot.summary.coverage)}}</text><view class="legend"><text>● 采购需求</text><text class="result">● 确认可供货</text><text class="shortage-key">● 明确缺货</text></view><view v-if="!snapshot.summary.orders" class="notice">当前接收批次暂无正式统计订单；确认日期趋势另按实际确认日选单。</view>
   <view class="chart"><text class="index">01 / FREQUENCY</text><text class="chart-title">医院要货次数</text><text class="muted">同一接收批次，每张采购单只计一次。</text><button v-for="r in snapshot.charts.frequency" :key="r.hospitalId" class="chart-row" :disabled="locked" @click="drill({chart:'frequency',hospitalId:r.hospitalId})"><view class="row-head"><text>{{r.hospitalName}}</text><text>{{r.orders}} 单 ›</text></view><view class="track"><view class="demand" :style="{width:barWidth(r.orders,maxOrders)+'%'}"></view></view></button><text v-if="!snapshot.charts.frequency.length" class="empty">无匹配订单</text></view>
   <view class="chart"><text class="index">02 / QUANTITY</text><text class="chart-title">需求与确认数量</text><text class="muted">同一接收批次，截至查询时的确认结果。</text><button v-for="r in snapshot.charts.quantity" :key="r.hospitalId" class="chart-row" :disabled="locked" @click="drill({chart:'quantity',hospitalId:r.hospitalId})"><view class="row-head"><text>{{r.hospitalName}}</text><text>需求 {{r.demandQuantity}} kg ›</text></view><view class="track"><view class="demand" :style="{width:barWidth(r.demandQuantity,maxQuantity)+'%'}"></view></view><view class="track"><view class="confirmed" :style="{width:barWidth(r.confirmedQuantity,maxQuantity)+'%'}"></view></view><text class="caption">确认 {{quantityLabel(r.confirmedQuantity,r.coverage,'confirmed')}} · 待确认 {{r.coverage.pendingOrders}} 单</text></button><text v-if="!snapshot.charts.quantity.length" class="empty">无匹配订单</text></view>
   <view class="chart"><text class="index">03 / TREND</text><text class="chart-title">{{state.trend==='demand'?'接收日期 · 需求趋势':'实际确认日期 · 结果趋势'}}</text><view class="switch"><button :class="{active:state.trend==='demand'}" :disabled="locked" @click="state.trend='demand'">接收日期 · 需求</button><button :class="{active:state.trend==='confirmation'}" :disabled="locked" @click="state.trend='confirmation'">确认日期 · 结果</button></view><text class="muted">北京时间{{snapshot.filters.groupBy==='month'?'自然月':'自然周（周一开始）'}}；两种视图分别选单，不可相加。标签显示完整自然期间，仅计本次筛选订单。左右滑动查看，点击点位核对订单。</text>
    <scroll-view v-if="plotPoints.length" scroll-x class="plot-scroll"><view class="plot" :style="{width:plotWidth+'rpx'}"><text class="axis-unit">kg</text><view class="axis"></view><view v-for="(line,i) in plotLines" :key="i" :class="['plot-line',state.trend==='confirmation'?'confirmed':'demand']" :style="{left:line.left+'rpx',top:line.top+'rpx',width:line.width+'rpx',transform:'rotate('+line.angle+'deg)'}"></view><button v-for="p in plotPoints" :key="p.period" class="plot-hit" :aria-label="p.label+'，'+(p.value===null?'未知':p.value+' kg')+(p.notice?'，'+p.notice:'')+'，核对订单'" :disabled="locked" :style="{left:(p.x-110)+'rpx',top:(p.value===null?150:p.y-48)+'rpx'}" @click="drill({chart:state.trend==='demand'?'demandTrend':'confirmationTrend',period:p.period})"><text>{{p.value===null?'未知':p.value}}</text><view v-if="p.value!==null" :class="['dot',state.trend==='confirmation'?'confirmed':'demand']"></view></button><text v-for="p in plotPoints" :key="p.period+'label'" class="plot-label" :style="{left:(p.x-120)+'rpx'}"><text>{{p.label.split(' 至 ')[0]}}</text><text>至 {{p.label.split(' 至 ')[1]}}</text></text></view></scroll-view><text v-else class="empty">此日期口径暂无有依据的数据。</text>
    <view class="period-buttons"><button v-for="r in trend" :key="r.period" :disabled="locked" @click="drill({chart:state.trend==='demand'?'demandTrend':'confirmationTrend',period:r.period})">{{periodRangeLabel(r)}} · {{state.trend==='demand'?r.demandQuantity+' kg':quantityLabel(r.confirmedQuantity,r.coverage,'confirmed')}}{{periodOrderNotice(r)?' · '+periodOrderNotice(r):''}} ›</button></view>
    <text class="caption">实际确认日期趋势 {{snapshot.confirmationTrendCoverage.orders}} 单；确认量已知 {{snapshot.confirmationTrendCoverage.knownQuantityLines}} 行 / 未知 {{snapshot.confirmationTrendCoverage.unknownQuantityLines}} 行。接收批次另有 {{snapshot.confirmationTrendCoverage.unknownDateOrders}} 单确认日期未知，未分配到确认趋势。</text></view>
   <view class="chart"><text class="index">04 / MEDICINES</text><text class="chart-title">药品规格需求排名</text><text class="muted">按完整需求排序，同名不同规格分别统计。</text><button v-for="(r,i) in snapshot.charts.ranking" :key="JSON.stringify([r.name,r.spec])" class="chart-row" :disabled="locked" @click="drill({chart:'ranking',name:r.name,spec:r.spec})"><view class="row-head"><text>{{i+1}}. {{r.name}} · {{r.spec||'未填规格'}}</text><text>{{r.demandQuantity}} kg ›</text></view><view class="track"><view class="demand" :style="{width:barWidth(r.demandQuantity,maxRanking)+'%'}"></view></view></button><text v-if="!snapshot.charts.ranking.length" class="empty">无匹配药品</text></view>
   <view class="chart"><text class="index">05 / CONFIRMED RESULTS</text><text class="chart-title">最终确认中的缺货情况</text><text class="muted">只汇总有依据的结果，不用需求减确认推断缺货。</text><button v-for="r in snapshot.charts.shortage" :key="r.hospitalId" class="chart-row" :disabled="locked" @click="drill({chart:'shortage',hospitalId:r.hospitalId})"><view class="row-head"><text>{{r.hospitalName}}</text><text>核对订单 ›</text></view><view class="track stacked"><view class="confirmed" :style="{width:barWidth(r.confirmedQuantity,maxShortage)+'%'}"></view><view class="missing" :style="{width:barWidth(r.missingQuantity,maxShortage)+'%'}"></view></view><text class="caption">可供 {{quantityLabel(r.confirmedQuantity,r.coverage,'confirmed')}}</text><text class="caption">缺货 {{quantityLabel(r.missingQuantity,r.coverage,'missing')}}</text><text class="caption">{{coverageLabel(r.coverage)}}</text></button><text v-if="!snapshot.charts.shortage.length" class="empty">无匹配结果</text></view>
   <view v-if="state.selection" class="drill"><view class="row-head"><text class="chart-title">对应订单核对{{selectedPeriod?' · '+selectedPeriod:''}}</text><button :disabled="locked" @click="controller.closeDrill()">收起</button></view><text class="muted">与本次图表使用同一查询快照，打开的业务档案可能晚于本次分析。</text><text v-if="state.drillLoading" class="empty">正在读取快照订单…</text><view v-if="state.drillError" class="error"><text>{{state.drillError}}</text><button :disabled="locked" @click="controller.move(state.selection.page||1)">重试本页</button></view><template v-if="state.drill"><view v-for="o in state.drill.items" :key="o.id" class="order"><text class="hospital">{{o.hospitalName}}</text><text class="tiny">{{o.orderNo}}</text><text class="caption">接收 {{o.receivedDate}} · {{o.confirmed?'实际确认 '+(o.confirmedDate||'日期未知'):'待医院确认'}}</text><text class="caption">需求 {{o.demandQuantity}} kg</text><text class="caption">确认 {{quantityLabel(o.confirmedQuantity,o.coverage,'confirmed')}}</text><text class="caption">缺货 {{quantityLabel(o.missingQuantity,o.coverage,'missing')}}</text><text class="caption">{{coverageLabel(o.coverage)}}</text><text class="tiny">{{o.entryMode==='historical_backfill'?'历史已核实':'冻结采购'}} R{{o.revisionNo}} · {{o.revisionId}}</text><text class="tiny">{{o.confirmationSourceId?'最终来源 '+o.confirmationSourceId:'最终结果待确认'}}</text><button :disabled="locked" @click="openOrder(o.id)">查看当前档案{{o.writable?'':'（只读旧单）'}} ›</button></view><text v-if="!state.drill.items.length" class="empty">{{state.drill.total===0&&selectedPeriod?'期间无符合筛选订单。':'本页没有可核对的订单。'}}</text><view class="pagination"><button :disabled="locked||state.drill.page<=1" @click="controller.move(state.drill.page-1)">上一页</button><text>{{state.drill.page}} / {{pages}} · {{state.drill.total}} 单</text><button :disabled="locked||state.drill.page>=pages" @click="controller.move(state.drill.page+1)">下一页</button></view></template></view>
  </template>
 </view>
</template>
<style scoped>
.hospital-analytics{color:#243e4e;padding:24rpx 0}.eyebrow,.index{display:block;font-size:20rpx;letter-spacing:2rpx;color:#6b8291}.title{display:block;font-size:40rpx;font-weight:600;margin:12rpx 0 20rpx}.muted{display:block;font-size:24rpx;line-height:1.65;color:#728591}.filters{padding:22rpx 0 30rpx;border-bottom:1rpx solid #dfe7ec}.date-row{display:flex;gap:20rpx}.field{display:block;flex:1;min-width:0;margin:16rpx 0;font-size:23rpx;color:#597180}.field>text{display:block;margin-bottom:10rpx}.select,.field input{padding:16rpx 14rpx;border:1rpx solid #ccd9e2;border-radius:8rpx;background:white;min-height:42rpx;font-size:25rpx;color:#294a60}.hospital-analytics button{font-size:25rpx;line-height:1.5;padding:18rpx 20rpx;margin:0;background:#f7fafb;color:#2c5870;border-radius:8rpx}.hospital-analytics button::after{border:1rpx solid #cbd9e1}.hospital-analytics button[disabled]{opacity:.5}.hospital-analytics button.primary{background:#2e6480;color:white;margin-top:18rpx}.notice,.error{display:block;padding:22rpx;margin:20rpx 0;background:#edf4f7;font-size:24rpx;line-height:1.6}.error{color:#a34832;background:#fff0ec}.error button{margin-top:16rpx}.meta{padding:26rpx 0;font-size:23rpx;color:#637b8b;line-height:1.7}.meta>text{display:block}.tiny{display:block;font-size:21rpx;color:#7d8f9b;line-height:1.65;word-break:break-all}.summary{display:flex;gap:36rpx}.summary>view{flex:1}.stat{display:block;margin-top:12rpx;font-size:35rpx;font-weight:600}.confirmation-stat{display:block;margin:26rpx 0 16rpx;font-size:29rpx;font-weight:500;color:#3b8b79}.coverage,.caption{display:block;font-size:22rpx;color:#718693;line-height:1.7}.legend{display:flex;gap:22rpx;flex-wrap:wrap;margin-top:22rpx;font-size:22rpx;color:#3c708c}.result{color:#3b8b79}.shortage-key{color:#b5825e}.chart{padding:34rpx 0;border-bottom:1rpx solid #dfe7ec}.chart-title{display:block;font-size:31rpx;font-weight:500;margin:14rpx 0}.hospital-analytics .chart-row{display:block;width:100%;background:transparent;text-align:left;padding:24rpx 0;border-radius:0;white-space:normal}.chart-row::after{border:none}.row-head{display:flex;justify-content:space-between;align-items:center;gap:20rpx;font-size:24rpx;line-height:1.5}.row-head>text:first-child{flex:1}.track{display:flex;margin:16rpx 0 8rpx;height:16rpx;background:#edf2f5;border-radius:3rpx;overflow:hidden}.track>view{height:100%;flex-shrink:0}.demand{background:#3c708c}.confirmed{background:#3b8b79}.missing{background:#be8a62}.stacked{height:22rpx}.empty{display:block;padding:34rpx 0;color:#8798a2;font-size:25rpx}.switch{display:flex;gap:12rpx;margin:20rpx 0}.switch button{flex:1;font-size:23rpx;padding:16rpx 8rpx}.switch .active{background:#e3edf3}.plot-scroll{margin:20rpx 0}.plot{height:310rpx;position:relative}.axis{position:absolute;left:24rpx;right:0;top:210rpx;height:1rpx;background:#d3dfe6}.axis-unit{position:absolute;left:0;top:10rpx;font-size:20rpx;color:#6a8291}.plot-line{position:absolute;height:4rpx;transform-origin:0 50%}.hospital-analytics .plot-hit{position:absolute;width:220rpx;height:90rpx;padding:8rpx 0;background:transparent;text-align:center;font-size:20rpx;line-height:1.3;overflow:visible}.plot-hit::after{border:none}.dot{width:14rpx;height:14rpx;border:3rpx solid white;border-radius:50%;margin:8rpx auto}.plot-label{position:absolute;top:237rpx;width:240rpx;text-align:center;font-size:20rpx;color:#6c8290}.plot-label>text{display:block}.period-buttons{display:flex;flex-direction:column;gap:12rpx;margin:20rpx 0}.hospital-analytics .period-buttons button{font-size:22rpx;text-align:left;white-space:normal;width:100%}.drill{padding:30rpx 0}.order{padding:24rpx 0;border-bottom:1rpx solid #dfe7ec}.hospital{display:block;font-size:29rpx;font-weight:500;margin-bottom:10rpx}.order button{margin-top:18rpx;background:white}.pagination{display:flex;align-items:center;justify-content:space-between;gap:12rpx;padding:28rpx 0;font-size:21rpx}.pagination button{font-size:23rpx;padding:15rpx}
</style>
